def moving_average(signal: list[float], width: int) -> list[float]:

    out: list[float] = []
    running: float = 0.0
    for i in range(len(signal)):
        running += signal[i]
        if i >= width:
            running -= signal[i - width]
        span: int = min(i + 1, width)
        out.append(running / span)
    return out
